#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;
using static VfxKit.VfxLightningKit;

namespace VfxEffects
{
    // Generated by vfx-shader. Rebuilt from this script: edit here, not in the Inspector.
    // Lightning bolts left behind a moving object, set up like rpg-game's VFX_BossRaid_Knight_Lightning_Trail (read + rendered, numbers in
    // .claude/skills/vfx-shader/references/lightning-set.md): ONE layer, Mesh particles (thunder_mesh2, a zig-zag bolt ribbon) in WORLD space
    // so they stay where they were emitted, shader Particles/Lightning_CustomBlend (bolt from Guardian_Lightning3, colour from Gradient_lightning,
    // HDR orange tint), Custom1.x = cutoff curve, Custom1.y = random scroll. The reference root scale 0.1428 is replaced by a 0.5 world scale baked
    // into the sizes; no transform has a scale; Scaling Mode Hierarchy. The root carries VfxPathMover so the showcase moves it along a line.
    // Space (proposal): dir, the emitter travels 6 m along X at height 1 m (2.4 s, back again), 3/4 camera, trail of bolts ~1 m long.
    public static class LightningTrailBuild
    {
        const string Root = "Assets/VFX/LightningTrail";
        const string Lib = "Assets/VFX/_Imported/RpgGame/Lightning/";
        static readonly Vector3 From = new Vector3(-3f, 1f, 0f), To = new Vector3(3f, 1f, 0f);
        const float Leg = 2.4f;

        [MenuItem("VFX/LightningTrail/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");
            var main = ImportTexture(Lib + "Textures/Guardian_Lightning3.png", 512, clamp: false);   // scrolls in U: Repeat
            var gradient = ImportTexture(Lib + "Textures/Gradient_lightning.png", 64, clamp: true);
            var mat = LightningMaterial(Root + "/Materials/M_LightningTrail_Bolt.mat", main, gradient, new Color(9.45f, 2.66f, 0f, 1f), 2f, -0.07f, 0.4f, 3f, 1f);
            var mesh = AssetDatabase.LoadAssetAtPath<Mesh>(Lib + "Mesh/thunder_mesh2.fbx");

            var root = new GameObject("VFX_LightningTrail");
            var ps = ParticleOn(root, mat, lifetime: 1.2f, size: 1f, color: new Color(1f, 0.77f, 0.04f, 1f));
            Loop(ps, 2f);
            var m = ps.main;
            m.maxParticles = 1000;
            m.simulationSpace = ParticleSystemSimulationSpace.World;
            Range(ps, 0.3f, 1.2f, 0.2f, 0.5f);
            Size3D(ps, new Vector2(0.4f, 0.55f), new Vector2(0.32f, 0.56f), new Vector2(0.8f, 0.8f));   // reference x 0.8 (world scale 0.8 instead of 0.1428): bolts ~1.5 m
            m.startRotation3D = true;
            m.startRotationX = new ParticleSystem.MinMaxCurve(0f, 6.28318f);
            m.startRotationY = new ParticleSystem.MinMaxCurve(0f, 6.28318f);
            m.startRotationZ = 0f;
            var em = ps.emission; em.rateOverTime = 8f; em.rateOverDistance = 2f;   // reference 5 / s and 0.5 per m: denser so the trail reads em.SetBursts(new ParticleSystem.Burst[0]);
            var sh = ps.shape;
            sh.enabled = true; sh.shapeType = ParticleSystemShapeType.Sphere; sh.radius = 0.2f; sh.radiusThickness = 0f; sh.scale = new Vector3(1f, 5f, 1f);
            SizeOverLifetime(ps, 0f, 0.71f, 0.05f, 1f, 1f, 0.54f);
            LightningCustomData(ps, 0f, -0.47f, 1f, 1f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh; r.mesh = mesh;
            r.alignment = ParticleSystemRenderSpace.Local; r.sortMode = ParticleSystemSortMode.YoungestInFront; r.sortingOrder = 5; r.maxParticleSize = 0.5f;
            LightningStreams(ps);
            ResetTiling(mat);

            var mover = root.AddComponent<VfxPathMover>();
            mover.from = From; mover.to = To; mover.legSeconds = Leg; mover.pauseSeconds = 0.4f;

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_LightningTrail.prefab");
            var look = new Vector3(0f, 1f, 0f);
            const float d = 9f;
            var cam = look + new Vector3(0f, Mathf.Sin(40f * Mathf.Deg2Rad) * d, -Mathf.Cos(40f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, "LightningTrail", new[] { 0.4f, 0.8f, 1.2f, 1.6f, 2.0f, 2.4f, 2.7f, 3.0f }, cam, look, tt => Vector3.Lerp(From, To, Mathf.Clamp01(tt / Leg)));
        }

        public static void BuildBatch() => RunBatch(Build);
    }
}
#endif
